// Buffer A
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    float R = 1.0;
    float r = 0.61;
    float d = 0.3;

    vec3 color = vec3(0.0);
    float lineThickness = 0.025;

    float dist = 10.0;
    for (float time = iTime * 10.0; time < iTime * 10.0 + 0.3; time += 0.01) {
        float x = (R - r) * cos(time) + d * cos((R - r) / r * time);
        float y = (R - r) * sin(time) - d * sin((R - r) / r * time);

        vec2 point = vec2(x, y);
        dist = min(length(uv - point),dist);

    }
    if (dist < lineThickness) {
        color = vec3(1.0);
    } else {
        color = texture(iChannel0, fragCoord.xy / iResolution.xy).rgb * 0.999;
        color = color.x < 0.4 ? vec3(0.0) : color;
    }

    fragColor = vec4(color, 1.0);
}
